#!/usr/bin/env python3
"""Run the invocations generated by generate_invocations.py.

Each invocation is executed in its own temporary directory, into which the model
files referenced by the command are copied (or, for a bundle, linked) first. The combined output (stdout and
stderr) of the command is written to the log file of the invocation.

Several invocations run at the same time, each pinned to its own physical cores and
limited in memory by BenchExec (see requirements.txt); by default as many as fit into
the cores and the memory of the machine. With --sequential, they run one after the
other without BenchExec, pinning and memory limit.
"""

import argparse
import glob
import concurrent.futures
import json
import logging
import os
import shlex
import shutil
import signal
import subprocess
import sys
import queue
import tempfile
import time
from pathlib import Path

from commands import BUNDLE_KEYS, CMD_KEYS, FILE_KEYS, PLACEHOLDER, pick_command, placeholders

# The experiment directory, e.g. comparison_tools_bisim; the scripts are run from there.
ROOT = Path.cwd()
BENCHMARK_DIR = ROOT / "benchmarks"

# Seconds to wait for a killed process to actually terminate.
KILL_GRACE = 5

# Memory left to the system when choosing the number of jobs: this fraction of the
# total memory, but at least SPARE_MEMORY_MIN GiB.
SPARE_MEMORY_FRACTION = 0.1
SPARE_MEMORY_MIN = 8
# Physical cores left to the system (run.py itself, BenchExec, Docker) when choosing
# the number of jobs.
SPARE_CORES = 1


class NotApplicable(Exception):
    """The configuration cannot be run on the benchmark, so there is nothing to do."""


def substitute(cmd, values):
    """Substitute the placeholders in a command line, yielding a list of arguments.

    A placeholder without a value makes its argument disappear; if that argument was
    preceded by an option, the option disappears as well. This way a benchmark
    without constants gets no '--constants' argument at all.
    """
    args = []
    for token in shlex.split(cmd):
        names = PLACEHOLDER.findall(token)
        if any(values.get(n) is None for n in names):
            if args and args[-1].startswith("-"):
                args.pop()
            continue
        args.append(PLACEHOLDER.sub(lambda m: values[m.group(1)], token))
    return args


def resolve_binary(bin):
    """The absolute path of the tool binary."""
    path = Path(os.path.expanduser(bin))
    if not path.is_absolute():
        if len(path.parts) == 1:
            found = shutil.which(str(path))
            if found:
                return Path(found)
        path = ROOT / path
    return path


def prepare(invocation):
    """The binary, the command line and the model files of an invocation.

    Raises NotApplicable if the configuration does not fit the benchmark and
    ValueError if the invocation is broken in some other way.
    """
    config, benchmark = invocation["config"], invocation["benchmark"]
    cmd = pick_command(config, benchmark)
    if cmd is None:
        raise NotApplicable(f"configuration '{config['id']}' is not applicable to "
                            f"benchmark '{benchmark['id']}'")
    binary = resolve_binary(config["bin"])
    if not binary.is_file():
        raise ValueError(f"binary not found: {binary}")
    files = {}
    for name in placeholders(cmd):
        if name in FILE_KEYS and name in benchmark:
            source = BENCHMARK_DIR / benchmark[name]
            if name in BUNDLE_KEYS:
                if not bundle_files(source):
                    raise ValueError(f"model files not found: {source}.*")
            elif not source.is_file():
                raise ValueError(f"model file not found: {source}")
            files[name] = source
    return binary, cmd, files


def bundle_files(prefix):
    """The files of a bundle, i.e. those whose name is the prefix plus an extension."""
    return sorted(prefix.parent.glob(glob.escape(prefix.name) + ".*"))


def execute(args, cwd, timelimit):
    """Run a command, aborting it when it exceeds the time limit.

    Returns (output, wall_time, return_code); the return code is None on a timeout.
    """
    start = time.time()
    # Own session, so that the whole process tree can be killed on a timeout.
    proc = subprocess.Popen(args, cwd=cwd, stdin=subprocess.DEVNULL,
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                            start_new_session=True)
    timeout = False
    try:
        try:
            output, _ = proc.communicate(timeout=timelimit)
        except subprocess.TimeoutExpired:
            timeout = True
            output = terminate(proc)
    except KeyboardInterrupt:
        terminate(proc)
        raise
    wall_time = time.time() - start
    return output.decode("utf8", errors="replace"), wall_time, None if timeout else proc.returncode


def terminate(proc):
    """Kill the process tree of proc and return whatever output it produced."""
    for sig in (signal.SIGTERM, signal.SIGKILL):
        try:
            os.killpg(proc.pid, sig)
        except ProcessLookupError:
            break
        try:
            output, _ = proc.communicate(timeout=KILL_GRACE)
            return output
        except subprocess.TimeoutExpired:
            continue
    try:
        output, _ = proc.communicate(timeout=KILL_GRACE)
    except subprocess.TimeoutExpired:
        output = b""
    return output


def run(invocation, execute=execute):
    """Run a single invocation and write its log file. Returns a status string."""
    config, benchmark = invocation["config"], invocation["benchmark"]
    log = Path(invocation["log"])
    timelimit = invocation["timelimit"]

    try:
        binary, cmd, files = prepare(invocation)
    except NotApplicable as e:
        return "skipped", 0.0, str(e)
    except ValueError as e:
        log.write_text(f"Error:\t{e}\n")
        return "error", 0.0, str(e)

    log.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="invocation-") as tmp:
        values = {k: v for k, v in benchmark.items() if k not in ("id", "type")}
        for name, source in files.items():
            if name in BUNDLE_KEYS:
                for file in bundle_files(source):
                    (Path(tmp) / file.name).symlink_to(file.resolve())
            else:
                shutil.copy2(source, Path(tmp) / source.name)
            values[name] = source.name
        args = [str(binary)] + substitute(cmd, values)
        output, wall_time, return_code = execute(args, tmp, timelimit)

    header = (f"Command:\t{shlex.join(args)}\n"
              f"Benchmark:\t{benchmark['id']}\n"
              f"Configuration:\t{config['id']}\n"
              f"Repetition:\t{invocation.get('repetition', 1)}\n"
              f"Time limit:\t{timelimit}\n"
              f"Output:\n")
    footer = f"\n{'-' * 40}\nWallclock time:\t{wall_time:.3f}\nReturn code:\t{return_code}\n"
    if return_code is None:
        footer += (f"Computation aborted after {wall_time:.3f} seconds since the time limit "
                   f"of {timelimit} seconds was exceeded.\n")
    log.write_text(header + output + footer)

    if return_code is None:
        return "timeout", wall_time, None
    if return_code != 0:
        return "error", wall_time, f"return code {return_code}"
    return "ok", wall_time, None


def pinned_execute(executor, cores, memlimit):
    """An execute() that runs the command with BenchExec, pinned to the given cores."""
    def execute(args, cwd, timelimit):
        with tempfile.TemporaryDirectory(prefix="output-") as out:
            output_file = Path(out) / "output"
            result = executor.execute_run(args, str(output_file), workingDir=cwd,
                                          walltimelimit=timelimit, cores=cores,
                                          memlimit=memlimit, write_header=False)
            output = output_file.read_text(errors="replace") if output_file.exists() else ""
        exit_code = result.get("exitcode")
        if result.get("terminationreason") == "failed":
            return output, result.get("walltime", 0.0), "BenchExec failed"
        if result.get("terminationreason") == "walltime" or exit_code is None:
            return output, result["walltime"], None
        # A negative signal as with subprocess, so that a kill by the memory limit is a memout.
        return output, result["walltime"], -exit_code.signal if exit_code.signal else exit_code.value
    return execute


def boost_enabled():
    """Whether the CPU may boost above its base frequency, None if unknown."""
    cpu = Path("/sys/devices/system/cpu")
    for path, enabled in [(cpu / "cpufreq/boost", "1"), (cpu / "intel_pstate/no_turbo", "0")]:
        if path.is_file():
            return path.read_text().strip() == enabled
    return None


def physical_cores(cpus):
    """The number of physical cores the given CPUs (hardware threads) belong to."""
    cores = set()
    for cpu in cpus:
        topology = Path(f"/sys/devices/system/cpu/cpu{cpu}/topology")
        cores.add(((topology / "physical_package_id").read_text().strip(),
                   (topology / "core_id").read_text().strip()))
    return len(cores)


def total_memory():
    """The total memory of the machine in GiB."""
    with open("/proc/meminfo") as f:
        for line in f:
            if line.startswith("MemTotal:"):
                return int(line.split()[1]) / 2**20
    sys.exit("cannot read the total memory from /proc/meminfo")


def default_jobs(cpus, args):
    """As many jobs as fit, with some cores and memory to spare, into the physical
    cores and the memory of the machine."""
    cores = physical_cores(cpus)
    memory = total_memory()
    usable = memory - max(SPARE_MEMORY_MIN, SPARE_MEMORY_FRACTION * memory)
    jobs = min((cores - SPARE_CORES) // args.cores_per_run, int(usable // args.memlimit))
    print(f"jobs: {jobs} ({cores} physical cores with {args.cores_per_run} per run and "
          f"at least {SPARE_CORES} to spare, {memory:.0f} GiB of memory with "
          f"{args.memlimit:g} GiB per run and {memory - usable:.0f} GiB to spare)")
    if jobs < 1:
        sys.exit("not enough cores or memory for a single run; "
                 "lower --cores-per-run or --memlimit")
    return jobs


def run_pinned(selected, counts, args):
    """Run the invocations args.jobs at a time, each pinned to its own physical cores."""
    try:
        from benchexec import resources, util
        from benchexec.cgroups import Cgroups
        from benchexec.runexecutor import RunExecutor
    except ImportError:
        sys.exit("run.py needs BenchExec, see requirements.txt, or use --sequential")
    cgroups = Cgroups.initialize()
    cgroups.handle_errors({s for s in (cgroups.CPUSET, cgroups.MEMORY, cgroups.FREEZE)
                           if not cgroups.require_subsystem(s)})
    cpus = util.parse_int_list(args.cores) if args.cores else sorted(os.sched_getaffinity(0))
    jobs = args.jobs if args.jobs is not None else default_jobs(cpus, args)
    # Without hyperthreading, the sibling of every assigned core stays idle.
    assignment = resources.get_cpu_cores_per_run(
        args.cores_per_run, jobs, False, cgroups,
        util.parse_int_list(args.cores) if args.cores else None)
    for number, cores in enumerate(assignment, start=1):
        governors = {Path(f"/sys/devices/system/cpu/cpu{c}/cpufreq/scaling_governor")
                     .read_text().strip() for c in cores}
        print(f"worker {number}: cores {','.join(map(str, cores))}, governor {'/'.join(governors)}")
        if governors != {"performance"}:
            print("  for stable timings run: sudo cpupower frequency-set -g performance")
    if boost_enabled():
        print("boost: enabled\n  for stable timings run: sudo cpupower set --turbo-boost 0")
    # In GiB, the unit of e.g. PRISM's -javamaxmem 32g.
    memlimit = int(args.memlimit * 2**30)
    print(f"memory limit: {args.memlimit:g} GiB per run")

    # Each worker takes a free executor, and with it its cores, for an invocation.
    executors = [RunExecutor(use_namespaces=False) for _ in assignment]
    free = queue.Queue()
    for executor, cores in zip(executors, assignment):
        free.put(pinned_execute(executor, cores, memlimit))

    def work(invocation):
        execute = free.get()
        try:
            return run(invocation, execute)
        finally:
            free.put(execute)

    # BenchExec logs every timeout and kill, which the progress output reports already.
    logging.getLogger().setLevel(logging.ERROR)
    # The runs finish out of order, so the progress counts the finished ones.
    width = len(str(len(selected)))
    start = time.time()
    pool = concurrent.futures.ThreadPoolExecutor(len(assignment))
    futures = {pool.submit(work, invocation): invocation for _, invocation in selected}
    try:
        for done, future in enumerate(concurrent.futures.as_completed(futures), start=1):
            invocation = futures[future]
            label = f"{invocation['config']['id']} {invocation['benchmark']['id']}"
            if "repetition" in invocation:
                label += f" rep{invocation['repetition']}"
            status, wall_time, note = future.result()
            counts[status] += 1
            elapsed = int(time.time() - start)
            print(f"[done {done:>{width}}/{len(selected)}, {elapsed // 3600}h {elapsed // 60 % 60:02d}m] "
                  f"{label} ... {status} ({wall_time:.1f}s)" + (f": {note}" if note else ""),
                  flush=True)
    except KeyboardInterrupt:
        pool.shutdown(wait=False, cancel_futures=True)
        for executor in executors:
            executor.stop()
        sys.exit("aborted")
    pool.shutdown()


def main():
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("invocations", help="json file as written by generate_invocations.py")
    parser.add_argument("--entry", type=int, metavar="I",
                        help="run only the I-th invocation (1-based, as numbered in the output)")
    parser.add_argument("--dry-run", action="store_true",
                        help="only show what would be run, do not execute anything")
    parser.add_argument("--jobs", type=int, metavar="N",
                        help="run N invocations at the same time, each pinned to its own "
                             "physical cores by BenchExec (default: as many as fit into "
                             "the cores and the memory)")
    parser.add_argument("--cores-per-run", type=int, default=4, metavar="C",
                        help="physical cores of each run, e.g. for the threads of Sylvan "
                             "and the garbage collector of Java (default: 4)")
    parser.add_argument("--cores", metavar="LIST",
                        help="CPUs to use, e.g. 2-11 (default: all)")
    parser.add_argument("--memlimit", type=float, default=32, metavar="GIB",
                        help="memory limit of each run, in GiB (default: 32)")
    parser.add_argument("--sequential", action="store_true",
                        help="run the invocations one after the other without BenchExec, "
                             "i.e. without pinning and memory limit")
    args = parser.parse_args()
    if args.sequential and (args.jobs is not None or args.cores):
        sys.exit("--sequential cannot be combined with --jobs or --cores")

    with open(args.invocations) as f:
        invocations = json.load(f)
    if not isinstance(invocations, list):
        sys.exit(f"{args.invocations}: expected a JSON array")

    selected = list(enumerate(invocations, start=1))
    if args.entry is not None:
        if not 1 <= args.entry <= len(invocations):
            sys.exit(f"--entry must be between 1 and {len(invocations)}, got {args.entry}")
        selected = [selected[args.entry - 1]]

    if args.dry_run:
        for _, invocation in selected:
            try:
                binary, cmd, files = prepare(invocation)
            except NotApplicable as e:
                print(f"skipped: {e}")
                continue
            except ValueError as e:
                print(f"! {e}")
                continue
            values = {k: v for k, v in invocation["benchmark"].items() if k not in ("id", "type")}
            values.update({n: s.name for n, s in files.items()})
            print(f"{invocation['log']}: {shlex.join([str(binary)] + substitute(cmd, values))}")
        return

    counts = {"ok": 0, "timeout": 0, "error": 0, "skipped": 0}
    width = len(str(len(invocations)))
    if not args.sequential:
        run_pinned(selected, counts, args)
    else:
        print("note: with --sequential, the memory limit is not enforced")
        for number, invocation in selected:
            label = f"{invocation['config']['id']} {invocation['benchmark']['id']}"
            if "repetition" in invocation:
                label += f" rep{invocation['repetition']}"
            print(f"[{number:>{width}}/{len(invocations)}] {label} ... ", end="", flush=True)
            try:
                status, wall_time, note = run(invocation)
            except KeyboardInterrupt:
                print("interrupted")
                sys.exit("aborted")
            counts[status] += 1
            print(f"{status} ({wall_time:.1f}s)" + (f": {note}" if note else ""), flush=True)

    print(f"\n{len(selected)} invocations: "
          f"{counts['ok']} ok, {counts['timeout']} timeout, {counts['error']} error, "
          f"{counts['skipped']} skipped")


if __name__ == "__main__":
    main()
